CustomField.formula:
IF(
    VALUE($Label.Working_Days) = 5,

    /* 5-day working week: Sat + Sun excluded */
    CASE(
        MOD(Last_Service_Date__c + 90 - DATE(1900, 1, 7), 7),
        0, Last_Service_Date__c + 91,
        6, Last_Service_Date__c + 92,
        Last_Service_Date__c + 90
    ),

    /* 6-day working week: Only Sun excluded */
    IF(
        MOD(Last_Service_Date__c + 90 - DATE(1900, 1, 7), 7) = 0,
        Last_Service_Date__c + 91,
        Last_Service_Date__c + 90
    )
)
